def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        if opp.get('budget', 0) >= budget:
            rich_opponents += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    base = 38.0
    if supply <= 16:
        base = 66.0
    elif supply <= 18:
        base = 58.0
    elif supply >= 23:
        base = 28.0
    elif supply >= 21:
        base = 34.0

    if highest_prev >= 88:
        base += 8.0
    elif highest_prev >= 78:
        base += 5.0
    elif avg_prev <= 55 and avg_prev > 0:
        base -= 4.0

    base += urgent_opponents * 2.0
    if rich_opponents >= 2:
        base += 3.0

    if hp <= 2:
        base = max(base, 82.0)
    elif hp <= 4:
        base = max(base, 68.0)
    elif no_water_days >= 2:
        base = max(base, 86.0)
    elif no_water_days >= 1:
        base = max(base, 72.0)

    if day >= 8 and hp > 4 and no_water_days == 0 and supply >= 20:
        base -= 6.0

    affordable_cap = budget
    if day < 10:
        reserve = max(0.0, (10 - day) * 8.0)
        affordable_cap = max(0.0, budget - reserve)
        if affordable_cap < 20.0:
            affordable_cap = min(budget, max(20.0, budget * 0.6))

    bid = min(base, budget, affordable_cap)
    if hp <= 2 or no_water_days >= 2:
        bid = min(max(bid, 88.0), budget)

    if not alive_opponents:
        bid = min(budget, 25.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # If no opponents, bid low to save budget
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            # Only consider valid bids, not 0.0 if they failed to bid or died
            if prev['bid'] > 0:
                yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure and my HP
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were bidding very high (high pressure)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # If I have good HP, I can afford to risk losing to save budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If HP is low, bid very aggressively to survive
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # Normal pressure: bid slightly above the highest previous bid, with a floor
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no yesterday_bids (e.g., first day, or all opponents didn't bid/died)
    if my_status['hp'] <= 2: # Critical HP, bid aggressively
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    # Otherwise, bid moderately
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If we are desperate or opponent pressure high, adjust
        if hp <= 2:
            # desperate, need water at any cost
            bid = min(budget, DAILY_SALARY * 0.95)
        elif hp <= 4:
            # somewhat low, be slightly aggressive
            bid = min(budget, max(DAILY_SALARY * 0.6, highest_prev + 2.0))
        else:
            # healthy, can be conservative, beat highest if possible but not overpay
            bid = min(budget, max(DAILY_SALARY * 0.4, highest_prev + 1.5))
    else:
        # no yesterday info, use base heuristic
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        elif hp <= 4:
            bid = min(budget, DAILY_SALARY * 0.6)
        else:
            bid = min(budget, DAILY_SALARY * 0.45)

    # Ensure bid does not exceed budget
    if bid > budget:
        bid = budget
    # Ensure bid is at least 0
    if bid < 0:
        bid = 0
    return bid
